    // Release the backing store's resources. Idempotent.
    //
    // # Errors
    //
    // Whatever [`ReviewStore::close`] returns.
    suspend fun close(): Unit {
        withContext(Dispatchers.IO) { withHandle { handle -> HaciendaBridge.nativeReviewQueueClose(handle) } }
    }

    override fun close() = synchronized(handleLock) {
        if (nativeHandle != 0L) {
            val handle = nativeHandle
            nativeHandle = 0L
            HaciendaBridge.nativeFreeReviewQueue(handle)
        }
    }
}
@Suppress("TooManyFunctions")
class Segment internal constructor(handle: Long) : AutoCloseable {
    private val handleLock = Any()
    private var nativeHandle: Long = handle

    internal fun <T> withHandle(block: (Long) -> T): T = synchronized(handleLock) {
        check(nativeHandle != 0L) { "Segment is closed" }
        block(nativeHandle)
    }
    companion object {
        private val MAPPER = com.fasterxml.jackson.databind.ObjectMapper()
            .registerModule(com.fasterxml.jackson.datatype.jdk8.Jdk8Module())
            .findAndRegisterModules()
            .setPropertyNamingStrategy(com.fasterxml.jackson.databind.PropertyNamingStrategies.SNAKE_CASE)
            .configure(com.fasterxml.jackson.databind.DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false)
    }

    // Mint an entry at the current tip and append it.
    //
    // Delegates to [`AuditChain::push`], which stamps the chain's own config hash onto
    // the input. Segment and chain are given the same config hash at
    // [`open`](Self::open), so a caller cannot put the two out of step.
    fun push(input: AuditEntryInput): AuditEntry {
        val responseJson = withHandle { handle -> HaciendaBridge.nativeSegmentPush(handle, MAPPER.writeValueAsString(input)) }
        return MAPPER.readValue(responseJson, AuditEntry::class.java)
    }

    // Seal this segment, producing an immutable [`SegmentSeal`] that commits to all
    // segment metadata. The `Segment` is consumed — no further entries can be appended.
    fun seal(): SegmentSeal {
        val responseJson = withHandle { handle -> HaciendaBridge.nativeSegmentSeal(handle) }
        return MAPPER.readValue(responseJson, SegmentSeal::class.java)
    }

    // Unique identifier for this segment.
    fun id(): String {
        return withHandle { handle -> HaciendaBridge.nativeSegmentId(handle) }
    }

    // The node that owns this segment.
    fun nodeId(): NodeId {
        val handle = withHandle { handle -> HaciendaBridge.nativeSegmentNodeId(handle) }
        return NodeId(handle)
    }

    // The tenant this segment belongs to.
    fun tenantId(): TenantId {
        val handle = withHandle { handle -> HaciendaBridge.nativeSegmentTenantId(handle) }
        return TenantId(handle)
    }

    // Chain hash of the most recent entry, or `GENESIS_HASH` when empty.
    fun tip(): String {
        return withHandle { handle -> HaciendaBridge.nativeSegmentTip(handle) }
    }

    // Number of entries pushed so far.
    fun len(): Long {
        return withHandle { handle -> HaciendaBridge.nativeSegmentLen(handle) }
    }

    // `true` when no entries have been pushed.
    fun isEmpty(): Boolean {
        return withHandle { handle -> HaciendaBridge.nativeSegmentIsEmpty(handle) }
    }

    // All entries in this segment, in push order.
    fun entries(): List<AuditEntry> {
        val responseJson = withHandle { handle -> HaciendaBridge.nativeSegmentEntries(handle) }
        return MAPPER.readValue(responseJson, object : TypeReference<List<AuditEntry>>() {})
    }

    // Append a pre-minted entry read back from storage, rejecting it if it does not extend
    // this segment's chain.
    //
    // This is the recovery counterpart to [`push`](Self::push): `push` mints a new entry,
    // this validates one that already exists on disk. Delegating to
    // [`AuditChain::append`] means a replayed file that was edited on disk fails at load
    // time rather than being silently adopted into a live chain — which is the property
    // that makes `FileAuditStore::open` fail on a tampered `.jsonl`.
    //
    // # Errors
    //
    // - [`AuditError::ConfigMismatch`] — the entry was minted under a different config.
    // - [`AuditError::ChainIntegrity`] — the entry's chain hash does not follow the tip.
    fun append(entry: AuditEntry): Unit {
        withHandle { handle -> HaciendaBridge.nativeSegmentAppend(handle, MAPPER.writeValueAsString(entry)) }
    }

    // Verify the internal entry chain — delegates to [`AuditChain::verify`], unchanged.
    //
    // This confirms that no entry within this segment was tampered with. It says nothing
    // about the link to adjacent segments; use [`verify_seal_chain`] for that.
    fun verify(): Unit {
        withHandle { handle -> HaciendaBridge.nativeSegmentVerify(handle) }
    }

    override fun close() = synchronized(handleLock) {
        if (nativeHandle != 0L) {
            val handle = nativeHandle
            nativeHandle = 0L
            HaciendaBridge.nativeFreeSegment(handle)
        }
    }
}
